let seed = 11;
const rand = (m) => { seed = (seed * 48271) % 2147483647; return seed % m; };
function brute(nums, goal) {
  let best = 0;
  for (let i = 0; i < nums.length; i++) { let s = 0; for (let j = i; j < nums.length; j++) { s += nums[j]; if (s >= goal) { if (best === 0 || j - i + 1 < best) best = j - i + 1; break; } } }
  return best;
}
for (let t = 0; t < 40; t++) {
  const nums = Array.from({ length: rand(13) }, () => rand(10));
  const goal = 1 + rand(30);
  assertEqual(minSubarrayLen(nums, goal), brute(nums, goal), JSON.stringify(nums) + ' goal=' + goal);
}
